 * recoverVok: Vok: dor -> pex, no additional preconditions.
 */
export function recoverVok(world: WorldState): WorldState {
  if (world.vok !== "dor") {
    throw new Error("recoverVok: Vok must be in state 'dor'");
  }
  return { ...world, vok: "pex" };
}
