        throw new Error(`Unknown entity: ${entityDisplayName}`);
    }
  },

  toAbstractSnapshot(state: any): Record<string, string> {
    const world = state as WorldState;
    return {
      Vok: world.vok,
      Zef: world.zef,
      Tal: world.tal,
      Fen: world.fen,
      Osk: world.osk,
    };
  },
};
